<?php $pageTitle='Enquiries';require __DIR__.'/_top.php';$rows=db()->query("SELECT * FROM enquiries ORDER BY created_at DESC")->fetchAll(); ?><section class="panel"><span class="eyebrow">INBOX</span><h2>Website enquiries</h2><div class="table-wrap"><table><thead><tr><th>From</th><th>Subject</th><th>Message</th><th>Received</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= e($r['name']) ?></b><small class="subline"><?= e($r['email']) ?></small></td><td><?= e($r['subject']) ?></td><td><?= e($r['message']) ?></td><td><?= e(date('d M Y',strtotime($r['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4">No enquiries received.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/_bottom.php'; ?>
